'use strict';
/* Administration : revue sur les objets autorisés, sans brouillon demandeur ni calcul local. */
(() => {
 const esc=v=>String(v??'Non renseigné').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const api=()=>window.CreditServices.api;const names={individuals:'Particulier',businesses:'Entreprise / PME',not_started:'À examiner',internal_review:'Revue ouverte',second_validation:'Seconde validation attendue',approved:'Approuvé en interne',not_approved:'Non approuvé',needs_completion:'À compléter',superseded:'Version à réexaminer',pending:'En attente',completed:'Terminé',failed:'Échec',confirmed:'Confirmé',warnings:'Avertissements',not_required:'Non requis',running:'En cours',blocked:'Bloqué',not_assessed:'Non évaluée',partially_reviewed:'Transcription partiellement revue'};
 const titles={value:'Valeur contrôlée',evidence_ids:'Références sources',reason:'Justification',name:'Identité / dénomination',currency:'Devise',profile:'Profil',periods:'Budget et flux par période',evidence:'Preuves et références',analysis_details:'Informations complémentaires d’analyse',record_details:'Informations du dossier',requested_loan:'Crédit demandé',existing_debts:'Dettes existantes',reserve:'Réserve mobilisable',initial_cash:'Trésorerie initiale',household_scope:'Périmètre du ménage',data_classification:'Nature des données',deposit_status:'Dépôt',quality_status:'Qualité',ocr_status:'OCR',review_status:'Revue des transcriptions',authenticity_status:'Authenticité',incomes:'Revenus',essential_expenses:'Dépenses essentielles',receipts:'Encaissements',operating_expenses:'Dépenses d’exploitation'};const name=x=>names[x]||titles[x]||x;const when=x=>x?new Date(x).toLocaleDateString('fr-FR'):'Non renseignée';let filter='',offset=0;let imageUrls=[];let epoch=0;const detailTabs=new Map();
 function cleanup(){epoch++;imageUrls.forEach(u=>URL.revokeObjectURL(u));imageUrls=[];}window.addEventListener('hashchange',cleanup);
 const facts=o=>'<dl class="centre-facts">'+Object.entries(o||{}).map(([k,v])=>'<div><dt>'+esc(titles[k]||k.replaceAll('_',' '))+'</dt><dd>'+(v&&typeof v==='object'?Array.isArray(v)?v.map(x=>typeof x==='object'?facts(x):esc(x)).join('<br>'):facts(v):esc(v===null?'Inconnu':v))+'</dd></div>').join('')+'</dl>';
 const msg=(root,e)=>{const box=root.querySelector('[data-review-error]');if(box){box.hidden=false;box.textContent=e.message}};
 async function queue(){const data=await api().request('/institution-admin/review-cases?limit=30&offset='+offset+(filter?'&core='+filter:''));return {heading:['Vérification des dossiers.','Contrôlez les données et les justificatifs avant toute approbation interne.'],html:`<div class="admin-review-toolbar"><label>Type de dossier<select id="admin-review-filter"><option value="">Tous les dossiers</option><option value="individuals" ${filter==='individuals'?'selected':''}>Particuliers</option><option value="businesses" ${filter==='businesses'?'selected':''}>Entreprises / PME</option></select></label><p>${data.total} dossier(s) de votre institution · ${data.items.length} affiché(s)</p></div><p data-review-error class="centre-warning" hidden role="alert"></p><div class="admin-review-grid">${data.items.map(c=>`<article class="admin-review-card"><div class="centre-card-top"><span class="mini-kicker">${name(c.kind)}</span><span class="centre-badge">${esc(c.review_case_version&&c.review_case_version!==c.version?'Version à réexaminer':name(c.review_state))}</span></div><h2>${esc(c.name)}</h2><p>Version ${c.version} · actualisé le ${when(c.updated_at)}</p><p>${c.document_count} pièce(s) · ${c.analysis_count} analyse(s)</p><small>Référence : ${esc(c.id)}</small><button class="primary" data-claim-review="${c.id}">Prendre en charge et examiner →</button></article>`).join('')||'<section class="centre-empty"><h2>Aucun dossier à afficher</h2><p>Les dossiers de votre institution apparaîtront ici après leur enregistrement. Aucun dossier de démonstration n’est ajouté automatiquement.</p></section>'}</div><div class="centre-actions"><button class="outline" id="admin-review-prev" ${offset===0?'disabled':''}>Précédent</button><button class="outline" id="admin-review-next" ${offset+data.items.length>=data.total?'disabled':''}>Suivant</button></div>`,bind(view){view.querySelector('#admin-review-filter').onchange=e=>{filter=e.target.value;offset=0;window.renderApp()};view.querySelector('#admin-review-prev').onclick=()=>{offset=Math.max(0,offset-30);window.renderApp()};view.querySelector('#admin-review-next').onclick=()=>{offset+=30;window.renderApp()};view.querySelectorAll('[data-claim-review]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const c=data.items.find(x=>x.id===b.dataset.claimReview);await api().request('/institution-admin/review-cases/'+c.id+'/claim',{method:'POST',body:{expected_revision:c.version}});location.hash='admin-centre/review/'+c.kind+'/'+c.id}catch(e){msg(view,e);b.disabled=false}})}};}
 async function detail(core,id){if(!['individuals','businesses'].includes(core)||!id)throw Error('Dossier invalide.');const path='/'+core+'/'+encodeURIComponent(id);const [c,subs,analyses,catalog]=await Promise.all([api().request(path),api().request(path+'/submissions'),api().request(path+'/assessments'),api().request('/documents/catalog')]);for(const sub of subs){const item=catalog.find(x=>x.id===sub.document_type);sub.document_title=item?.title||sub.document_type;sub.field_titles=Object.fromEntries((item?.fields||[]).map(f=>[f.key,f.aliases?.[0]||f.key]));}return {heading:['Examen du dossier.','Revue manuelle · '+name(core)+' · version '+c.version],html:`<a class="text-button" href="#admin-centre/reviews">← File des vérifications</a><section class="admin-case-header"><span class="mini-kicker">${name(core)}</span><h2>${esc(c.data.name)}</h2><p>Référence ${esc(c.id)} · version ${c.version}</p><p>La revue d’une transcription, la validation interne et la décision bancaire sont trois opérations distinctes.</p></section><nav class="centre-tabs" aria-label="Étapes de vérification">${[['data','Données du dossier'],['documents','Pièces & transcriptions'],['analysis','Résultats d’analyse'],['decision','Revue & approbation']].map(([key,title],i)=>`<button class="outline" type="button" data-admin-tab="${key}" aria-pressed="${i===0}" aria-controls="admin-panel-${key}">${title}</button>`).join('')}</nav><p data-review-error class="centre-warning" role="alert" hidden></p><section id="admin-panel-data" class="centre-panel"><h2>Données enregistrées</h2><p>Valeurs déclarées ou contrôlées telles qu’enregistrées, sans modification du dossier depuis cet écran.</p>${Object.entries(c.data).map(([k,v])=>`<details class="admin-data-section"><summary>${esc(titles[k]||k.replaceAll('_',' '))}</summary>${facts({[k]:v})}</details>`).join('')}</section><section id="admin-panel-documents" class="centre-panel" hidden><h2>Contrôler les pièces</h2><p>Consultez les pages sources et corrigez les transcriptions. Ce contrôle ne certifie pas l’authenticité et n’envoie aucune valeur directement au scoring.</p><div class="admin-document-list">${subs.map(s=>`<button class="outline" data-open-submission="${s.id}">${esc(s.document_title||s.document_type)} · ${esc(name(s.review_status))}</button>`).join('')||'<p>Aucune pièce déposée.</p>'}</div><div id="admin-document-workspace"></div></section><section id="admin-panel-analysis" class="centre-panel" hidden><h2>Analyses enregistrées</h2><p>Résultats du serveur conservés avec leur version. Aucun score n’est recalculé dans cet écran.</p><label class="centre-field"><span>Choisir une analyse</span><select id="admin-analysis-select"><option value="">Sélectionnez une édition</option>${analyses.map(a=>`<option value="${a.id}">${when(a.created_at)} · ${esc(a.engine_version)} · ${esc(a.id)}</option>`).join('')}</select></label><div id="admin-analysis-result">${analyses.length?'':'Aucune analyse disponible. Une approbation ne peut pas remplacer une analyse manquante.'}</div></section><section id="admin-panel-decision" class="centre-panel" hidden><div id="admin-internal-review">Chargement de la revue institutionnelle…</div></section>`,bind(view){let selected=detailTabs.get(id)||'data',reviewLoaded=false;view.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=async()=>{selected=b.dataset.adminTab;detailTabs.set(id,selected);view.querySelectorAll('[id^=admin-panel-]').forEach(p=>p.hidden=p.id!=='admin-panel-'+selected);view.querySelectorAll('[data-admin-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(selected==='decision'&&!reviewLoaded){const box=view.querySelector('#admin-internal-review');try{const result=await window.CreditBanking.reviewPanel(box,api(),{core,id});if(!box.isConnected)return;box.innerHTML=result.html;result.bind?.();reviewLoaded=true;}catch(e){box.textContent=e.message;}}});if(selected!=='data')view.querySelector('[data-admin-tab="'+selected+'"]').click();view.querySelectorAll('[data-open-submission]').forEach(b=>b.onclick=()=>documentReview(view,path,subs.find(s=>s.id===b.dataset.openSubmission)).catch(e=>msg(view,e)));view.querySelector('#admin-analysis-select').onchange=async e=>{const box=view.querySelector('#admin-analysis-result'),aid=e.target.value;if(!aid){box.textContent='Sélectionnez une analyse.';return}try{const r=await api().request('/assessments/'+aid);if(!box.isConnected||e.target.value!==aid)return;const result=r.result||r.data?.result||r;box.innerHTML=Array.isArray(result.sections)?window.CreditInstitutions.renderSections(result):'<p>Analyse incomplète : résultats disponibles uniquement.</p>'+facts(result)}catch(error){msg(view,error)}};}};}
 async function documentReview(view,path,s){cleanup();const generation=epoch,root=view.querySelector('#admin-document-workspace');root.innerHTML='<p>Chargement de la pièce et de ses références…</p>';const documentTitle=s.document_title||s.document_type,fieldTitles=s.field_titles||{};s={...await api().request(path+'/submissions/'+s.id),document_title:documentTitle,field_titles:fieldTitles};const prefix=path+'/submissions/'+s.id;let run=s.latest_run_id?await api().request(prefix+'/runs/'+s.latest_run_id):null;if(!root.isConnected||generation!==epoch)return;const extraction=run?.extraction;root.innerHTML=`<h3>${esc(s.document_title)}</h3><div class="centre-badge-row">${['deposit_status','quality_status','ocr_status','review_status','authenticity_status'].map(k=>`<span class="centre-badge">${esc(titles[k]||k.replaceAll('_',' '))} : ${esc(name(s[k]||'not_assessed'))}</span>`).join('')}</div><div class="admin-source-pages">${(s.pages||[]).map((p,i)=>`<figure><div data-source-page="${p.id}">Chargement…</div><figcaption>Page ${i+1} · source ${esc(p.source_page)}</figcaption></figure>`).join('')}</div><div class="centre-actions">${s.deposit_status==='confirmed'?'<button class="outline" id="admin-process-document">Traiter / relancer l’extraction</button>':''}${(s.sources||[...new Set((s.pages||[]).map(p=>p.source_id))].map(id=>({id}))).map(f=>`<button class="outline" data-original-source="${f.id}">Télécharger l’original</button>`).join('')}</div>${extraction?`<details><summary>Extraction brute, coordonnées et limites</summary>${facts(extraction)}</details><form id="admin-transcription-form" class="centre-form"><h3>Valider ou corriger une transcription</h3><label class="centre-field"><span>Champ à contrôler</span><select name="field" required><option value="">Choisir un champ</option>${Object.keys(extraction.fields||{}).map(k=>`<option value="${esc(k)}">${esc(fieldTitles[k]||k)}</option>`).join('')}</select></label><div id="admin-raw-candidate"></div><label class="centre-field"><span>Valeur contrôlée — montants exacts, sans arrondi ajouté</span><input name="value" required maxlength="2000"></label><label class="centre-field"><span>Références sources — sélection obligatoire</span><select name="evidence" multiple required size="5">${[...(extraction.evidence||[]),...(extraction.tables||[]),...(extraction.form_fields||[])].map(e=>`<option value="${esc(e.id)}">Page ${esc(e.page)} · ${esc(e.id)} · ${esc(String(e.text||e.name||'Zone source').slice(0,100))}</option>`).join('')}</select></label><label class="centre-field"><span>Justification du contrôle ou de la correction</span><textarea name="reason" required maxlength="2000"></textarea></label><label class="check-field"><input type="checkbox" name="confirmed" required><span>J’ai comparé la valeur aux pages sources sélectionnées.</span></label><button class="primary" type="submit">Enregistrer le contrôle humain</button></form><h3>Historique des contrôles</h3>${(run.reviews||[]).map(r=>'<article class="admin-review-history"><h4>Contrôle par '+esc(r.actor_id)+'</h4><p>'+esc(when(r.created_at))+' · Référence '+esc(r.id)+'</p>'+facts(r.decisions||{})+'</article>').join('')||'<p>Aucun contrôle enregistré.</p>'}`:'<p>Extraction indisponible. Le dépôt reste conservé ; aucune donnée absente n’est transformée en zéro.</p>'}<p id="admin-document-feedback" role="status"></p>`;
 root.querySelectorAll('[data-source-page]').forEach(async box=>{try{const blob=await api().request(prefix+'/pages/'+box.dataset.sourcePage+'/image',{responseType:'blob'});if(!box.isConnected||generation!==epoch)return;const url=URL.createObjectURL(blob);imageUrls.push(url);const image=new Image();image.alt='Page source du document '+s.document_type;image.src=url;const zoom=document.createElement('button');zoom.type='button';zoom.className='text-button';zoom.textContent='Agrandir la page ↗';zoom.onclick=()=>window.open(url,'_blank','noopener');box.replaceChildren(image,zoom)}catch(e){box.textContent=e.message}});
 root.querySelectorAll('[data-original-source]').forEach(b=>b.onclick=async()=>{try{const blob=await api().request(prefix+'/sources/'+b.dataset.originalSource,{responseType:'blob'});const url=URL.createObjectURL(blob);imageUrls.push(url);const a=document.createElement('a');a.href=url;a.download='original-'+b.dataset.originalSource;a.click()}catch(e){msg(view,e)}});
 const process=root.querySelector('#admin-process-document');if(process)process.onclick=async()=>{process.disabled=true;try{await api().request(prefix+'/process',{method:'POST',body:{},timeoutMs:120000});await documentReview(view,path,s)}catch(e){msg(view,e);process.disabled=false}};
 const form=root.querySelector('#admin-transcription-form');if(form){form.elements.field.onchange=()=>{root.querySelector('#admin-raw-candidate').innerHTML=facts(extraction.fields[form.elements.field.value]||{});form.elements.value.value='';form.elements.confirmed.checked=false};form.onsubmit=async e=>{e.preventDefault();const data=new FormData(form);form.querySelector('button').disabled=true;try{await api().request(prefix+'/runs/'+run.id+'/reviews',{method:'POST',body:{expected_review_revision:s.review_revision||0,decisions:{[data.get('field')]:{value:data.get('value'),evidence_ids:data.getAll('evidence'),reason:data.get('reason')}}}});await documentReview(view,path,s);view.querySelector('#admin-document-feedback').textContent='Contrôle enregistré avec auteur, date et sources. Authenticité non certifiée.'}catch(error){msg(view,error);form.querySelector('button').disabled=false}};}
 }
 window.CreditAdminReviews={queue,detail,cleanup};
})();
